CREATE TABLE "adaptive_runs" ("adaptiveRunId" UUID PRIMARY KEY,"scopeKey" TEXT NOT NULL UNIQUE,"learnerId" UUID NOT NULL,"contextId" TEXT NOT NULL,"academicVersionId" TEXT NOT NULL,"status" TEXT NOT NULL,"selectedCandidateId" TEXT,"watermarkEffectiveAt" TIMESTAMP(3),"watermarkSourceRank" INTEGER,"watermarkSourceId" TEXT,"activeGenerationId" UUID,"engineId" TEXT NOT NULL,"algorithmId" TEXT NOT NULL,"configId" TEXT NOT NULL,"processingVersion" TEXT NOT NULL,"contractVersion" TEXT NOT NULL,"revision" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "adaptive_runs_scope_unique" UNIQUE("learnerId","contextId","academicVersionId"));
CREATE INDEX "adaptive_runs_learner_context_idx" ON "adaptive_runs"("learnerId","contextId");
CREATE TABLE "adaptive_generations" ("generationId" UUID PRIMARY KEY,"logicalKey" TEXT NOT NULL UNIQUE,"scopeKey" TEXT NOT NULL,"learnerId" UUID NOT NULL,"fingerprint" TEXT NOT NULL,"sourceIds" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "adaptive_generations_scope_idx" ON "adaptive_generations"("scopeKey","createdAt");
CREATE TABLE "adaptive_candidates" ("adaptiveCandidateId" UUID PRIMARY KEY,"generationId" UUID NOT NULL,"immutableCandidateId" TEXT NOT NULL,"scopeKey" TEXT NOT NULL,"learnerId" UUID NOT NULL,"candidateType" TEXT NOT NULL,"conceptId" TEXT NOT NULL,"targetRefId" TEXT NOT NULL,"eligible" BOOLEAN NOT NULL,"exclusionReason" TEXT,"revisionUrgency" DECIMAL(12,6) NOT NULL,"mistakeUrgency" DECIMAL(12,6) NOT NULL,"masteryGap" DECIMAL(12,6) NOT NULL,"confidenceGap" DECIMAL(12,6) NOT NULL,"difficultyFit" DECIMAL(12,6) NOT NULL,"noveltyNeed" DECIMAL(12,6) NOT NULL,"finalScore" DECIMAL(12,6) NOT NULL,"rank" INTEGER,"reasonCodes" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "adaptive_candidates_generation_identity_unique" UNIQUE("generationId","immutableCandidateId"));
CREATE INDEX "adaptive_candidates_scope_generation_rank_idx" ON "adaptive_candidates"("scopeKey","generationId","rank");
CREATE TABLE "adaptive_explanations" ("adaptiveExplanationId" UUID PRIMARY KEY,"generationId" UUID NOT NULL UNIQUE,"scopeKey" TEXT NOT NULL,"learnerId" UUID NOT NULL,"selectedCandidateId" TEXT,"reasonCodes" JSONB NOT NULL,"explanation" TEXT NOT NULL,"engineId" TEXT NOT NULL,"configId" TEXT NOT NULL,"processingVersion" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "adaptive_history" ("adaptiveHistoryId" UUID PRIMARY KEY,"projectionId" TEXT NOT NULL UNIQUE,"generationId" UUID NOT NULL,"scopeKey" TEXT NOT NULL,"learnerId" UUID NOT NULL,"selectedCandidateId" TEXT,"reasonCodes" JSONB NOT NULL,"explanation" TEXT NOT NULL,"watermarkEffectiveAt" TIMESTAMP(3) NOT NULL,"watermarkSourceRank" INTEGER NOT NULL,"watermarkSourceId" TEXT NOT NULL,"engineId" TEXT NOT NULL,"algorithmId" TEXT NOT NULL,"configId" TEXT NOT NULL,"processingVersion" TEXT NOT NULL,"contractVersion" TEXT NOT NULL,"provenance" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "adaptive_history_generation_scope_unique" UNIQUE("generationId","scopeKey"));
CREATE INDEX "adaptive_history_scope_created_idx" ON "adaptive_history"("scopeKey","createdAt");
CREATE TABLE "adaptive_source_ledger" ("adaptiveSourceLedgerId" UUID PRIMARY KEY,"scopeKey" TEXT NOT NULL,"learnerId" UUID NOT NULL,"immutableSourceId" TEXT NOT NULL,"payloadHash" TEXT NOT NULL,"effectiveAt" TIMESTAMP(3) NOT NULL,"sourceRank" INTEGER NOT NULL,"normalizedPayload" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "adaptive_source_scope_id_unique" UNIQUE("scopeKey","immutableSourceId"));
CREATE INDEX "adaptive_source_order_idx" ON "adaptive_source_ledger"("scopeKey","effectiveAt","sourceRank","immutableSourceId");
CREATE OR REPLACE FUNCTION reject_adaptive_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'adaptive_history is append-only'; END; $$;
CREATE TRIGGER adaptive_history_immutable BEFORE UPDATE OR DELETE ON "adaptive_history" FOR EACH ROW EXECUTE FUNCTION reject_adaptive_history_mutation();
